 static void RoundIntegration(){foreach(var profile in new[]{R24MeleeProfiles.Katana,R24MeleeProfiles.Excalibur,R24MeleeProfiles.Cyberblade}){var round=new R23RoundState(new[]{"target"},new Cases(),true);string id;Need(round.CreateWeaponInstance(profile.Id,5,out id),"actual round constructs each source sword native lifetime");R23WeaponInstanceInfo info;Need(round.TryReadWeaponInstance(id,out info)&&info.ProfileId==profile.Id&&info.Stars==1&&info.Capacity==0&&info.BodyDamage==0,"source non-tiered metadata has no fictional flat firearm damage");Need(round.SelectWeapon(id)&&round.ActiveLoaded==0&&round.ActiveReserve==0&&!round.Step(.01f,true,false,false),"source sword trigger has no projectile/ammo");var owner=round.Melee;Need(owner!=null&&owner.Profile==profile&&round.ReadMeleeInstance(id)==owner,"exact action owns exact source mechanism");owner.BeginFrame(.1f,true,Unit,profile.Base,profile.Tip,new Float3(),new string[0]);var delta=new Float3(.2f,0,0);var sweep=owner.BeginFrame(.1f,true,Unit,R24KnifeMath.Add(profile.Base,delta),R24KnifeMath.Add(profile.Tip,delta),delta,new string[0]);var entries=owner.SampleStep(sweep,0,new[]{"target"},new[]{"target"},new[]{"target"});Need(entries.Length==1&&round.ApplyKnifeContact(id,entries[0])&&round.ReadTarget("target").Health==25&&round.ReadTarget("target").Shield==100,"native sword75 bypasses native target shield");Need(!round.ApplyKnifeContact(id,entries[0])&&round.Hits==1,"source sword contact entry cannot repeat native damage");Need(round.SelectWeapon("cx4")&&round.ReadMeleeInstance(id)==owner&&!round.ApplyKnifeContact(id,entries[0]),"switch retains identity and rejects old contact");Need(round.SelectWeapon(id)&&round.ReadMeleeInstance(id).AcceptedContacts==1&&round.ReadReserve(id)==0,"re-equip retains contact lifetime and zero ammo entitlement");Need(round.ReadAmmoReserveFamily("rifle")==2400&&round.ReadAmmoReserveFamily("pistol")==1200,"sword creates no family reserve debit/grant");round.Reset();Need(round.ResolveWeaponProfile(id)==null&&round.ReadMeleeInstance(profile.Id)!=null,"restart retires independent copy and reconstructs source default world owner");}}
 static void Main(){RoundIntegration();foreach(var profile in new[]{R24MeleeProfiles.Katana,R24MeleeProfiles.Excalibur,R24MeleeProfiles.Cyberblade}){var r=new R24MeleeRuntime("source/"+profile.Id,profile);Need(r.Profile.Id==profile.Id&&r.DamageFor(0)==25&&r.DamageFor(1)==50&&r.DamageFor(2)==75&&r.DamageFor(99)==75,"actual source sword hand-speed damage curve");Need(r.BladeBasePoint.Y==.125f&&r.BladeTipPoint.Y>1.11f&&r.BladeTipPoint.Y<1.12f,"genuine source measured marker span, no knife geometry reuse");r.BeginFrame(.1f,true,Unit,profile.Base,profile.Tip,new Float3(),new string[0]);var s=r.BeginFrame(.1f,true,Unit,R24KnifeMath.Add(profile.Base,new Float3(.2f,0,0)),R24KnifeMath.Add(profile.Tip,new Float3(.2f,0,0)),new Float3(.2f,0,0),new string[0]);var entries=r.SampleStep(s,0,new[]{"enemy"},new[]{"enemy"},new[]{"enemy"});Need(entries.Length==1&&entries[0].Damage==75,"real native contact records current sword speed damage");Need(r.ApplyContact(entries[0],delegate(string id,float amount){return id=="enemy"&&amount==75;}),"actual source sword contact applies exact owner decision");r.SuspendControls();Need(!r.ApplyContact(entries[0],delegate{return true;}),"sword contact cannot outlive suspended frame");r.UpdateSupport(true,true,false,true,.25f);Need(!r.Supported,"loaded held support grip starts neutral-rearmed");r.UpdateSupport(true,true,false,false,.25f);r.UpdateSupport(true,true,false,true,.28f);Need(r.Supported&&r.SupportAcquired&&r.Snapshot.ClaimsSupport,"actual source hilt .28 acquisition reserves support");r.UpdateSupport(true,true,false,true,.33f);Need(r.Supported&&!r.SupportAcquired,"actual hilt .34 release hysteresis");r.UpdateSupport(true,true,false,true,.341f);Need(!r.Supported,"hilt beyond .34 releases");r.UpdateSupport(true,true,false,true,.25f);Need(r.Supported,"source ordinary reentry while held after successful rearm");BulletGuard guard;Need(r.TryReadBulletGuard(Unit,true,out guard)==(profile.Id=="katana"),"only real two-hand katana provides finite bullet guard");if(profile.Id=="katana"){Need(r.MovementGain==.90f,"source shield movement .90");float fraction;Need(guard.Intersects(new Float3(0,.34f,1),new Float3(0,.34f,-1),out fraction)&&Math.Abs(fraction-.46f)<.0001f,"actual native finite front guard intercept");Need(!guard.Intersects(new Float3(0,.34f,-1),new Float3(0,.34f,1),out fraction),"rear bullet does not block");Need(!guard.Intersects(new Float3(R24MeleeRuntime.ShieldHalfWidth+.001f,.34f,1),new Float3(R24MeleeRuntime.ShieldHalfWidth+.001f,.34f,-1),out fraction),"no infinite/rounded boundary beyond source rectangle");Need(!r.TryReadBulletGuard(Unit,false,out guard),"unusable actor cannot retain rendered shield authority");}else Need(r.MovementGain==1.25f,"source speed/energy sword movement1.25");r.UpdateSupport(true,true,true,true,.2f);Need(!r.Supported&&!r.ShieldActive,"actual reserved/climbing support releases shield/hilt");r.Retire();Need(r.BeginFrame(.1f,true,Unit,profile.Base,profile.Tip,new Float3(),new string[0])==null,"retired sword lifetime cannot create contacts");}
 var k=new R24KnifeRuntime("legacy-knife");Need(k.DamageFor(0)==35&&k.DamageFor(2)==35&&k.BladeTipPoint.Y==.246f,"legacy knife remains exact35 and short marker");k.UpdateSupport(true,true,false,false,.1f);k.UpdateSupport(true,true,false,true,.1f);Need(!k.Supported&&!k.ShieldActive&&k.MovementGain==1.15f,"knife never adopts sword support/shield");var heldKatana=new R24MeleeRuntime("katana-entry",R24MeleeProfiles.Katana);heldKatana.UpdateSupport(true,true,false,true,.4f);heldKatana.UpdateSupport(true,true,false,true,.25f);Need(heldKatana.Supported&&heldKatana.ShieldActive,"source katana held-grip outside-to-hilt acquisition exception");Need(Math.Abs(R24MeleeRuntime.ShieldHalfWidth-.48768f*48/41.5f)<.000001f&&Math.Abs(R24MeleeRuntime.ShieldHalfHeight-.6096f*48/41.5f)<.000001f,"source41.5to48 measurement applied once to guard");Console.WriteLine("PASS "+n+" staged actual source sword/native-contact/support/guard/movement cases");}
